def max_subarray(nums: list[int]) -> int:
    max_so_far = nums[0]  # Initialize max_so_far with the first element
    max_ending_here = nums[0]  # Initialize max_ending_here with the first element

    for num in nums[1:]:  # Iterate over the remaining elements
        max_ending_here = max(num, max_ending_here + num)  # Update max_ending_here with the maximum of the current number and the sum of max_ending_here and the current number
        if max_ending_here < 0:
            max_ending_here = 0  # If the sum becomes negative, reset max_ending_here to 0
        else:
            max_so_far = max(max_so_far, max_ending_here)  # Update max_so_far with the maximum of the current max_so_far and max_ending_here

    return max_so_far

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    intervals.sort(key=lambda x: x[0])

    result = []
    prev_end = None
    for interval in intervals:
        if prev_end is None or interval[0] <= prev_end:
            result.append([prev_end, interval[1]])
            prev_end = interval[1]
        else:
            result.append([prev_end, interval[0]])
            prev_end = interval[1]

    result.append([prev_end, intervals[-1][1]])

    return result

def longest_unique_substring(s: str) -> int:
    n = len(s)
    max_len = 1
    unique_char_index = [0] * 26

    for i, char in enumerate(s):
        if char in 'abcdefghijklmnopqrstuvwxyz':
            unique_char_index[ord(char) - ord('a')] += 1
            if unique_char_index[ord(char) - ord('a')] > max_len:
                max_len = unique_char_index[ord(char) - ord('a')]
        else:
            unique_char_index[ord(char) - ord('a')] = 0

        if i - max_len >= 0 and s[i - max_len] not in s[i - max_len:i]:
