def valid_brackets(s: str) -> bool:
    stack = []
    for char in s:
        if char in '[]{}':
            stack.append(char)
        elif char in '[]{}':
            if not stack:
                return False
            stack.pop()
    if len(stack) != 0:
        return False
    return len(stack) == 0

def min_coins(coins: list[int], amount: int) -> int:
    # Check if amount is negative or coins list is empty
    if amount < 0 or not coins:
        return -1

    # Create a dictionary to store the minimum number of coins needed for each partial sum
    coin_sum_dict = {}
    for coin in coins:
        if coin in coin_sum_dict:
            coin_sum_dict[coin] += 1
        else:
            coin_sum_dict[coin] = 1

    # Iterate through partial sums and find the minimum number of coins needed
    result = float('inf')
    for sum in range(1, amount + 1):
        if sum in coin_sum_dict:
            result = min(result, sum + coin_sum_dict[sum])

    return result if result != float('inf') else -1

def spiral_order(matrix: list[list[int]]) -> list[int]:
    m, n = len(matrix), len(matrix[0])
    direction = 1

    result = []
    top, bottom, left, right = m - 1, 0, n - 1, n - 1

    while top >= left and bottom >= right:
        for _ in range(top - left + 1):
            result.append(matrix[top][left])
            top -= 1

        for _ in range(right - bottom + 1):
            result.append(matrix[top][bottom])
            bottom += 1

        for _ in range(bottom - right - 1, -1, -1):
            result.append(matrix[right][bottom])
            bottom -= 1

        for _ in range(right - top + 1):
            result.append(matrix[top][right])
            top += 1

    return result

from math import sqrt

def count_primes(n: int) -> int:
    """Number of primes strictly less than n. 0 <= n <= 5*10^6.
    >>> count_primes(10)
    4
    >>> count_primes(20)
    8
    """
    if n <= 1:
        return 0
    primes = []
    for i in range(2, int(sqrt(n)) + 1):
        is_prime = True
        for j in range(2, int(sqrt(i)) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return len(primes) * (n // len(primes))

def count_pairs_with_sum(nums: list[int], target: int) -> int:
    count = 0
    num_len = len(nums)

    for i in range(num_len - 1):
        for j in range(i + 1, num_len):
            if nums[i] + nums[j] == target and nums[i] != 0:
                count += 1

    return count

def lis_length(nums: list[int]) -> int:
    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1

    return max(dp)

def running_median(nums: list[int]) -> list[float]:
    nums.sort()
    n = len(nums)
    if n % 2 == 0:
        mid = n // 2
        median1, median2 = nums[mid], nums[mid - 1]
        return (median1 + median2) / 2
    else:
        mid = n // 2
        return nums[mid]
